import unittest
from candidate import modp

class TestModp(unittest.TestCase):
    def test_modp_small_numbers(self):
        self.assertEqual(modp(3, 5), 3)

    def test_modp_large_numbers(self):
        self.assertEqual(modp(1101, 101), 2)

    def test_modp_base_case(self):
        self.assertEqual(modp(0, 101), 1)

    def test_modp_prime_modulus(self):
        self.assertEqual(modp(3, 11), 8)

    def test_modp_power_of_2(self):
        self.assertEqual(modp(100, 101), 1)

    def test_modp_negative_n(self):
        with self.assertRaises(ValueError):
            modp(-3, 5)

    def test_modp_negative_p(self):
        with self.assertRaises(ValueError):
            modp(3, -5)

    def test_modp_non_integer_n(self):
        with self.assertRaises(TypeError):
            modp(3.5, 5)

    def test_modp_non_integer_p(self):
        with self.assertRaises(TypeError):
            modp(3, 5.5)

    def test_modp_p_equals_1(self):
        with self.assertRaises(ValueError):
            modp(3, 1)

    def test_modp_p_equals_0(self):
        with self.assertRaises(ZeroDivisionError):
            modp(3, 0)

    def test_modp_n_equals_none(self):
        with self.assertRaises(TypeError):
            modp(None, 5)

    def test_modp_p_equals_none(self):
        with self.assertRaises(TypeError):
            modp(3, None)

if __name__ == '__main__':
    unittest.main()
